]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "同时变化时计算遗漏"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "溶质溶剂变化要分清变化对象。倒出溶液时溶质和溶液按比例减少，这是易错点。"}]}]}]}$$ AS jsonb), NULL, '数量关系-浓度问题-溶质溶剂变化的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "浓度问题", "溶质溶剂变化"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_conc_change", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
